'use client'

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  useSyncExternalStore,
  type CSSProperties,
  type ReactNode,
} from 'react'
import { DynamicIslandEngine, dynamicIslandSpring } from './dynamic-island.engine'

export interface DynamicIslandState {
  width: number
  height: number
  radius?: number
  bounce?: number
  label?: string
  content: ReactNode
}

export interface DynamicIslandOptions {
  bounce: number
  duration: number
  radius: number
  background: string
}

export interface DynamicIslandProps extends Partial<DynamicIslandOptions> {
  states: Record<string, DynamicIslandState>
  state?: string
  defaultState?: string
  onStateChange?: (state: string) => void
  className?: string
  style?: CSSProperties
}

export interface DynamicIslandContextValue {
  state: string
  setState: (state: string) => void
}

export const dynamicIslandDefaults: DynamicIslandOptions = {
  bounce: 0.2,
  duration: 800,
  radius: 32,
  background: '#000000',
}

interface Layer {
  id: number
  key: string
  shown: boolean
}

const MAX_DT = 1 / 30
const MOTION_QUERY = '(prefers-reduced-motion: reduce)'

const DynamicIslandContext = createContext<DynamicIslandContextValue | null>(null)

export function useDynamicIsland() {
  const context = useContext(DynamicIslandContext)
  if (!context) throw new Error('useDynamicIsland must be used inside a DynamicIsland')
  return context
}

function subscribeMotion(onChange: () => void) {
  const list = window.matchMedia(MOTION_QUERY)
  list.addEventListener('change', onChange)
  return () => list.removeEventListener('change', onChange)
}

function useReducedMotion() {
  return useSyncExternalStore(
    subscribeMotion,
    () => window.matchMedia(MOTION_QUERY).matches,
    () => false,
  )
}

const hasState = (states: Record<string, DynamicIslandState>, key: string) =>
  Object.hasOwn(states, key)

export function DynamicIsland({
  states,
  state,
  defaultState,
  onStateChange,
  bounce = dynamicIslandDefaults.bounce,
  duration = dynamicIslandDefaults.duration,
  radius = dynamicIslandDefaults.radius,
  background = dynamicIslandDefaults.background,
  className,
  style,
}: DynamicIslandProps) {
  const reduced = useReducedMotion()
  const first = Object.keys(states)[0] ?? ''
  const [internal, setInternal] = useState(() =>
    defaultState !== undefined && hasState(states, defaultState) ? defaultState : first,
  )
  const controlled = state !== undefined && hasState(states, state)
  const current = controlled ? state : hasState(states, internal) ? internal : first
  const target = states[current]
  const width = target?.width ?? 0
  const height = target?.height ?? 0
  const corner = target?.radius ?? radius
  const springBounce = target?.bounce ?? bounce

  const [initial] = useState(() => ({ width, height, radius: corner }))
  const [engine] = useState(() => {
    const created = new DynamicIslandEngine(initial)
    created.show(0, false)
    return created
  })
  const [layers, setLayers] = useState<Layer[]>(() => [{ id: 0, key: current, shown: true }])
  const newest = layers[layers.length - 1]
  if (newest && newest.key !== current) {
    setLayers([{ id: newest.id + 1, key: current, shown: reduced }])
  }
  const newestId = newest?.id ?? 0

  const rootRef = useRef<HTMLDivElement>(null)
  const layerEls = useRef(new Map<number, HTMLDivElement>())
  const statesRef = useRef(states)
  const layersRef = useRef(layers)
  const reducedRef = useRef(reduced)
  const wakeRef = useRef<() => void>(() => {})

  useLayoutEffect(() => {
    statesRef.current = states
    layersRef.current = layers
    reducedRef.current = reduced
  })

  useEffect(() => {
    const root = rootRef.current
    if (!root) return
    let frame = 0
    let last = 0
    let visible = true

    const apply = () => {
      const box = engine.box
      root.style.width = `${box.width}px`
      root.style.height = `${box.height}px`
      root.style.borderRadius = `${box.radius}px`
      for (const layer of layersRef.current) {
        const el = layerEls.current.get(layer.id)
        const size = statesRef.current[layer.key]
        if (!el || !size) continue
        const f = engine.frame(layer.id)
        const sx = size.width > 0 ? (box.width / size.width) * f.scale : f.scale
        const sy = size.height > 0 ? (box.height / size.height) * f.scale : f.scale
        el.style.opacity = String(f.opacity)
        el.style.filter = f.blur > 0.01 ? `blur(${f.blur}px)` : ''
        el.style.transform = `translate(-50%, -50%) scale(${sx}, ${sy})`
      }
    }

    const loop = (now: number) => {
      frame = 0
      const dt = last ? Math.min((now - last) / 1000, MAX_DT) : 0
      last = now
      engine.tick(dt)
      apply()
      if (!engine.idle && visible) frame = requestAnimationFrame(loop)
      else last = 0
    }

    wakeRef.current = () => {
      if (!visible || reducedRef.current) {
        if (frame) cancelAnimationFrame(frame)
        frame = 0
        last = 0
        engine.finish()
        apply()
      } else if (!frame && !engine.idle) {
        frame = requestAnimationFrame(loop)
      }
    }

    const observer = new IntersectionObserver(([entry]) => {
      visible = entry?.isIntersecting ?? true
      wakeRef.current()
    })
    observer.observe(root)
    wakeRef.current()

    return () => {
      observer.disconnect()
      if (frame) cancelAnimationFrame(frame)
      wakeRef.current = () => {}
    }
  }, [engine])

  useLayoutEffect(() => {
    if (!engine.visibleLayers().includes(newestId)) engine.show(newestId, !reduced)
    const box = { width, height, radius: corner }
    if (reduced) engine.jump(box)
    else engine.setTarget(box, dynamicIslandSpring(springBounce, duration))
    wakeRef.current()
  }, [engine, newestId, width, height, corner, springBounce, duration, reduced])

  const setState = useCallback(
    (next: string) => {
      if (!controlled) setInternal(next)
      onStateChange?.(next)
    },
    [controlled, onStateChange],
  )
  const context = useMemo(() => ({ state: current, setState }), [current, setState])

  return (
    <div
      ref={rootRef}
      className={['uig-dynamic-island', 'overflow-hidden contain-layout', className]
        .filter(Boolean)
        .join(' ')}
      style={{
        ...style,
        width: initial.width,
        height: initial.height,
        borderRadius: initial.radius,
        background,
      }}
    >
      <span className="uig-dynamic-island__status sr-only" role="status" aria-live="polite">
        {target?.label ?? current}
      </span>
      <DynamicIslandContext value={context}>
        {layers.map((layer) => {
          const item = states[layer.key]
          return (
            <div
              key={layer.id}
              ref={(el) => {
                if (el) layerEls.current.set(layer.id, el)
                return () => {
                  layerEls.current.delete(layer.id)
                }
              }}
              className="uig-dynamic-island__layer absolute top-1/2 left-1/2"
              style={{
                width: item?.width,
                height: item?.height,
                opacity: layer.shown ? 1 : 0,
                transform: 'translate(-50%, -50%)',
              }}
            >
              {item?.content}
            </div>
          )
        })}
      </DynamicIslandContext>
    </div>
  )
}

export interface DynamicIslandBox {
  width: number
  height: number
  radius: number
}

export interface DynamicIslandSpring {
  stiffness: number
  damping: number
  mass: number
}

export interface DynamicIslandLayerFrame {
  opacity: number
  blur: number
  scale: number
}

interface Channel {
  value: number
  velocity: number
  target: number
}

interface Layer {
  id: number
  start: number
}

const FADE_DELAY = 36
const POP_DELAY = 52
const FADE_MS = 300
const ENTER_MS = 440
const SCALE_FROM = 0.9
const BLUR_FROM = 5
const POP_STIFFNESS = 550
const POP_DAMPING = 30
const SETTLE_EPSILON = 0.001
// Critical damping reaches a thousandth once omega times duration hits this
const CRITICAL_SPAN = 9.2335
const REST_DELTA = 0.02
const REST_SPEED = 0.5

const clamp01 = (v: number) => (v < 0 ? 0 : v > 1 ? 1 : v)

function cubicBezier(x1: number, y1: number, x2: number, y2: number) {
  const cx = 3 * x1
  const bx = 3 * (x2 - x1) - cx
  const ax = 1 - cx - bx
  const cy = 3 * y1
  const by = 3 * (y2 - y1) - cy
  const ay = 1 - cy - by
  const sampleX = (t: number) => ((ax * t + bx) * t + cx) * t
  const slopeX = (t: number) => (3 * ax * t + 2 * bx) * t + cx
  return (x: number) => {
    if (x <= 0) return 0
    if (x >= 1) return 1
    let t = x
    for (let i = 0; i < 8; i++) {
      const error = sampleX(t) - x
      const slope = slopeX(t)
      if (Math.abs(error) < 1e-6 || Math.abs(slope) < 1e-6) break
      t = clamp01(t - error / slope)
    }
    return ((ay * t + by) * t + cy) * t
  }
}

const fade = cubicBezier(0.25, 0.1, 0.35, 1)

// Closed-form damped oscillator: new offset and velocity after dt
function step(x: number, v: number, dt: number, spring: DynamicIslandSpring) {
  const omega = Math.sqrt(spring.stiffness / spring.mass)
  const zeta = spring.damping / (2 * Math.sqrt(spring.stiffness * spring.mass))
  if (zeta < 1) {
    const decay = zeta * omega
    const damped = omega * Math.sqrt(1 - zeta * zeta)
    const envelope = Math.exp(-decay * dt)
    const cos = Math.cos(damped * dt)
    const sin = Math.sin(damped * dt)
    return {
      x: envelope * (x * cos + ((v + decay * x) / damped) * sin),
      v: envelope * (v * cos - ((decay * v + omega * omega * x) / damped) * sin),
    }
  }
  const envelope = Math.exp(-omega * dt)
  const b = v + omega * x
  return { x: envelope * (x + b * dt), v: envelope * (v - omega * b * dt) }
}

const pop: DynamicIslandSpring = { stiffness: POP_STIFFNESS, damping: POP_DAMPING, mass: 1 }

// Spring whose envelope decays to a thousandth within duration ms
export function dynamicIslandSpring(bounce: number, duration: number): DynamicIslandSpring {
  const seconds = Math.max(duration, 10) / 1000
  const zeta = Math.min(1, Math.max(0.05, 1 - bounce))
  const omega =
    zeta >= 0.99
      ? CRITICAL_SPAN / seconds
      : Math.log(zeta / (SETTLE_EPSILON * Math.sqrt(1 - zeta * zeta))) / (zeta * seconds)
  return { stiffness: omega * omega, damping: 2 * zeta * omega, mass: 1 }
}

export function dynamicIslandEnter(ms: number): DynamicIslandLayerFrame {
  if (ms >= ENTER_MS) return { opacity: 1, blur: 0, scale: 1 }
  const eased = fade((ms - FADE_DELAY) / FADE_MS)
  const t = Math.max(0, ms - POP_DELAY) / 1000
  const offset = step(1 - SCALE_FROM, 0, t, pop).x
  return { opacity: eased, blur: BLUR_FROM * (1 - eased), scale: 1 - offset }
}

export class DynamicIslandEngine {
  idle = true
  private channels: [Channel, Channel, Channel]
  private spring: DynamicIslandSpring = dynamicIslandSpring(0.2, 800)
  private layers: Layer[] = []
  private time = 0

  constructor(box: DynamicIslandBox) {
    this.channels = [
      { value: box.width, velocity: 0, target: box.width },
      { value: box.height, velocity: 0, target: box.height },
      { value: box.radius, velocity: 0, target: box.radius },
    ]
  }

  get box(): DynamicIslandBox {
    const [width, height, radius] = this.channels
    return {
      width: Math.max(0, width.value),
      height: Math.max(0, height.value),
      radius: Math.max(0, radius.value),
    }
  }

  setTarget(box: DynamicIslandBox, spring: DynamicIslandSpring) {
    this.spring = spring
    const [width, height, radius] = this.channels
    width.target = box.width
    height.target = box.height
    radius.target = box.radius
    this.idle = this.settled()
  }

  jump(box: DynamicIslandBox) {
    const targets = [box.width, box.height, box.radius]
    this.channels.forEach((channel, i) => {
      channel.value = channel.target = targets[i] ?? channel.value
      channel.velocity = 0
    })
    this.idle = this.settled()
  }

  // Old content leaves at once, only the new layer animates
  show(id: number, animate: boolean) {
    this.layers = [{ id, start: animate ? this.time : this.time - ENTER_MS }]
    this.idle = this.settled()
  }

  frame(id: number): DynamicIslandLayerFrame {
    const layer = this.layers.find((l) => l.id === id)
    if (!layer) return { opacity: 1, blur: 0, scale: 1 }
    return dynamicIslandEnter(this.time - layer.start)
  }

  visibleLayers() {
    return this.layers.map((layer) => layer.id)
  }

  finish() {
    for (const channel of this.channels) {
      channel.value = channel.target
      channel.velocity = 0
    }
    for (const layer of this.layers) layer.start = this.time - ENTER_MS
    this.idle = true
  }

  tick(dt: number) {
    this.time += dt * 1000
    for (const channel of this.channels) {
      if (channel.value === channel.target && channel.velocity === 0) continue
      const next = step(channel.value - channel.target, channel.velocity, dt, this.spring)
      if (Math.abs(next.x) < REST_DELTA && Math.abs(next.v) < REST_SPEED) {
        channel.value = channel.target
        channel.velocity = 0
      } else {
        channel.value = channel.target + next.x
        channel.velocity = next.v
      }
    }
    this.idle = this.settled()
  }

  private settled() {
    const still = this.channels.every((c) => c.value === c.target && c.velocity === 0)
    return still && this.layers.every((l) => this.time - l.start >= ENTER_MS)
  }
}
